        let mut env = indexmap::indexmap! {
            "mise_tool_opts__extensions".to_string() => "ambient".to_string(),
        };
        let mut options = ToolOptions::default();
        options
            .insert_option(
                "extensions".to_string(),
                toml::Value::String("configured".to_string()),
