/// right after it. This keeps a stale `10.0.0` entry from satisfying
/// `prefix:1` (which prefix resolution itself would never pick — it matches at
/// separator boundaries) and keeps an empty prefix from matching everything.
fn lockfile_version_matches_prefix_boundary(prefix: &str, version: &str) -> bool {
    let prefix = strip_leading_v(prefix);
    if prefix.is_empty() {
        return false;
    }
    match strip_leading_v(version).strip_prefix(prefix) {
        None => false,
        Some(rest) => rest.is_empty() || prefix.ends_with('-') || rest.starts_with(['.', '-', '+']),
    }
}

fn strip_leading_v(version: &str) -> &str {
    version
        .strip_prefix(['v', 'V'])
        .filter(|stripped| stripped.chars().next().is_some_and(|c| c.is_ascii_digit()))
        .unwrap_or(version)
}

/// Get the backend for a tool from the lockfile, ignoring options.
/// This is used for backend discovery where we just need any entry's backend.
pub(crate) fn get_locked_backend(config: &Config, short: &str) -> Option<String> {
    let settings = Settings::get();
    if !settings.lockfile_enabled() {
        return None;
    }

    let lockfile = read_all_lockfiles(config);

    lockfile
        .tools
        .get(short)
        .and_then(|tools| tools.first())
        .and_then(|tool| tool.backend.clone())
}

