local function process_gh_aw()
	local versions = {}

	local p = io.popen("git ls-remote --tags --refs https://github.com/github/gh-aw.git 2>/dev/null")
	if p then
		for line in p:lines() do
			local ref = line:match("%s+refs/tags/(.+)$")
