"vfox-npm:prettier" = "$latest_version"
EOF
cat <<EOF >mise.lock
[[tools."vfox-npm:prettier"]]
version = "$latest_version"
backend = "vfox-npm:prettier"
EOF
assert "mise install --locked --dry-run"

